"use client";

import { typography } from "../lib/typography.shared";
import { useId, useState, type ComponentProps } from "react";
import { Check } from "lucide-react";
import { cn } from "cn";
import { Badge } from "../components/badge";
import { Button } from "../components/button";
import { Table, TableHeader, TableBody, TableRow, TableHead, TableCell, TableCaption } from "../components/table";

interface PricingProps extends Omit<ComponentProps<"section">, "title"> {
  title?: string;
  description?: string;
  defaultBilling?: "monthly" | "yearly";
  plans?: {
    name: string;
    description: string;
    monthlyPrice: number;
    yearlyPrice: number;
    features: string[];
    href: string;
    label?: string;
    featured?: boolean;
  }[];
}

export function PricingComparison({ title = "A plan for every next step", description = "Start small. Make room as you grow.", defaultBilling = "monthly", plans = [{ name: "Starter", description: "For your next side project.", monthlyPrice: 0, yearlyPrice: 0, features: ["1 workspace", "Core components", "Community support"], href: "/signup", label: "Start for free" }, { name: "Pro", description: "For ideas ready to grow.", monthlyPrice: 19, yearlyPrice: 15, features: ["Unlimited workspaces", "All components and blocks", "Priority support"], href: "/signup?plan=pro", featured: true }, { name: "Team", description: "For building together.", monthlyPrice: 49, yearlyPrice: 39, features: ["Everything in Pro", "Team collaboration", "Dedicated support"], href: "/signup?plan=team" }], className, children, ...props }: PricingProps = {}) {
  const [billing, setBilling] = useState(defaultBilling);
  const id = useId();
  const actionClass = "inline-flex min-h-11 w-full items-center justify-center border border-border px-4 py-2 text-sm font-semibold focus-visible:outline-2 focus-visible:outline-ring";
  function price(plan: (typeof plans)[number]) { return billing === "yearly" ? plan.yearlyPrice : plan.monthlyPrice; }
  return (<section {...props} aria-labelledby={props["aria-labelledby"] ?? `${id}-title`} data-slot="pricing" data-layout="comparison" className={cn("@container w-full space-y-8 text-foreground", className)}>
    <div className="text-center"><h2 id={`${id}-title`} className={typography.sectionTitle}>{title}</h2><p className={`mt-3 ${typography.body}`}>{description}</p></div>
    <div role="group" aria-label="Billing period" className="flex justify-center gap-1">
      <Button variant={billing === "monthly" ? "primary" : "secondary"} aria-pressed={billing === "monthly"} onClick={() => setBilling("monthly")}>Monthly</Button>
      <Button variant={billing === "yearly" ? "primary" : "secondary"} aria-pressed={billing === "yearly"} onClick={() => setBilling("yearly")}>Yearly</Button>
    </div>
    <p aria-live="polite" className="text-center text-xs text-muted-foreground">{billing === "yearly" ? "Monthly prices shown. Billed once a year." : "Billed monthly. Switch to yearly for lower monthly prices."}</p>
    {<Table>
      <TableCaption>Compare plans. All prices are in USD.</TableCaption>
      <TableHeader><TableRow><TableHead>Plan</TableHead><TableHead>Price / month</TableHead><TableHead>Includes</TableHead><TableHead>Get started</TableHead></TableRow></TableHeader>
      <TableBody>{plans.map(plan => <TableRow key={plan.name} data-state={plan.featured ? "selected" : undefined}>
        <TableCell><span className="font-semibold">{plan.name}</span>{plan.featured && <div className="mt-2"><Badge variant="info">Popular</Badge></div>}</TableCell>
        <TableCell><span className="text-lg font-semibold">${price(plan)}</span>{billing === "yearly" && <p className="mt-1 text-xs text-muted-foreground">${price(plan) * 12} / year</p>}</TableCell>
        <TableCell><ul className="space-y-2">{plan.features.map(feature => <li key={feature} className="flex items-start gap-2"><Check size={14} aria-hidden="true" className="mt-1 shrink-0" />{feature}</li>)}</ul></TableCell>
        <TableCell><a href={plan.href} aria-label={`${plan.label ?? "Get started"} with ${plan.name}`} className={cn(actionClass, "whitespace-nowrap hover:bg-muted")}>{plan.label ?? "Get started"}</a></TableCell>
      </TableRow>)}</TableBody>
    </Table>}
    {children}
  </section>);
}

"use client";

import { memo, type ReactNode } from "react";
import * as motion from "motion/react-client";
import { useReducedMotion, type HTMLMotionProps } from "motion/react";
import { CircleCheck, CircleDashed, CircleX, Clock3, SearchCheck, Send, TriangleAlert } from "lucide-react";
import { typography } from "../lib/typography.shared";

interface BadgeProps extends Omit<HTMLMotionProps<"span">, "children"> {
  children?: ReactNode;
  variant?: "pending" | "in-progress" | "submitted" | "in-review" | "success" | "failed" | "expired" | "neutral" | "info" | "warning" | "error" | "blue" | "purple" | "pink" | "teal" | "orange";
}

const statuses = {
  pending: { label: "Pending", icon: TriangleAlert },
  "in-progress": { label: "In progress", icon: CircleDashed },
  submitted: { label: "Submitted", icon: Send },
  "in-review": { label: "In review", icon: SearchCheck },
  success: { label: "Success", icon: CircleCheck },
  failed: { label: "Failed", icon: CircleX },
  expired: { label: "Expired", icon: Clock3 },
};

const styles = {
  pending: "bg-orange-500/10 text-orange-500",
  "in-progress": "bg-sky-500/10 text-sky-500",
  submitted: "bg-violet-500/10 text-violet-500",
  "in-review": "bg-yellow-500/10 text-yellow-600 dark:text-yellow-400",
  success: "bg-green-500/10 text-green-600 dark:text-green-400",
  failed: "bg-red-500/10 text-red-500",
  expired: "bg-neutral-500/10 text-neutral-500",
  neutral: "bg-neutral-500/10 text-neutral-500",
  info: "bg-sky-500/10 text-sky-500",
  warning: "bg-amber-500/10 text-amber-600 dark:text-amber-400",
  error: "bg-red-500/10 text-red-500",
  blue: "bg-blue-500/10 text-blue-500",
  purple: "bg-purple-500/10 text-purple-500",
  pink: "bg-pink-500/10 text-pink-500",
  teal: "bg-teal-500/10 text-teal-600 dark:text-teal-400",
  orange: "bg-orange-500/10 text-orange-500",
};

export const Badge = memo(function Badge({ children, variant = "success", className = "", ...props }: BadgeProps = {}) {
  const status = variant in statuses ? statuses[variant as keyof typeof statuses] : undefined;
  const Icon = status?.icon;
  const reducedMotion = useReducedMotion();

  return (
    <motion.span
      initial={reducedMotion ? false : { opacity: 0, y: 20 }}
      whileInView={reducedMotion ? undefined : { opacity: 1, y: 0 }}
      viewport={{ once: true, amount: 0.5 }}
      whileHover={reducedMotion ? undefined : { y: -2, scale: 1.03 }}
      transition={{ duration: reducedMotion ? 0 : 0.35, ease: "easeOut" }}
      className={`inline-flex items-center gap-2 rounded-none border-0 px-3 py-2 ${typography.label} ${styles[variant]} ${className}`}
      {...props}
    >
      {Icon && <Icon aria-hidden="true" className="size-[1.15em] shrink-0" strokeWidth={2.25} />}
      {children ?? status?.label ?? "New release"}
    </motion.span>
  );
});

import { memo, type ComponentProps } from "react";

type ButtonProps = {
  variant?: "primary" | "secondary" | "ghost" | "destructive" | "outline";
} & (ComponentProps<"button"> & { href?: never } | ComponentProps<"a"> & { href: string });

export const Button = memo(function Button({
  children = "Get started",
  variant = "primary",
  className = "",
  ...props
}: ButtonProps = {}) {
  const styles = {
    primary: "bg-emerald-400 text-neutral-950 hover:bg-emerald-300",
    secondary: "bg-neutral-800 text-white hover:bg-neutral-700",
    ghost: "bg-transparent text-foreground hover:bg-muted",
    destructive: "bg-destructive text-destructive-foreground hover:bg-destructive/90",
    outline: "border border-border text-white hover:bg-neutral-800",
  };
  const classes = `inline-flex min-h-11 items-center justify-center gap-2 px-5 py-2 text-sm font-semibold transition-colors focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-emerald-400 disabled:pointer-events-none disabled:opacity-50 ${styles[variant] ?? styles.primary} ${className}`;

  if (props.href !== undefined) {
    return <a className={classes} {...props}>{children}</a>;
  }

  return (
    <button
      type="button"
      className={classes}
      {...props}
    >
      {children}
    </button>
  );
});

import type { ComponentProps } from "react";
import { cn } from "cn";

export function Table({ className, ...props }: ComponentProps<"table">) {
  return <div className="w-full overflow-x-auto border border-border"><table {...props} data-slot="table" className={cn("w-full caption-bottom text-left text-sm text-foreground", className)} /></div>;
}

export function TableHeader({ className, ...props }: ComponentProps<"thead">) {
  return <thead {...props} data-slot="table-header" className={cn("bg-muted text-muted-foreground [&_tr]:border-b", className)} />;
}

export function TableBody({ className, ...props }: ComponentProps<"tbody">) {
  return <tbody {...props} data-slot="table-body" className={cn("[&_tr:last-child]:border-0", className)} />;
}

export function TableFooter({ className, ...props }: ComponentProps<"tfoot">) {
  return <tfoot {...props} data-slot="table-footer" className={cn("border-t border-border bg-muted font-medium", className)} />;
}

export function TableRow({ className, ...props }: ComponentProps<"tr">) {
  return <tr {...props} data-slot="table-row" className={cn("border-b border-border transition-colors hover:bg-muted/50 data-[state=selected]:bg-muted", className)} />;
}

export function TableHead({ className, scope = "col", ...props }: ComponentProps<"th">) {
  return <th {...props} scope={scope} data-slot="table-head" className={cn("px-4 py-3 align-middle font-medium", className)} />;
}

export function TableCell({ className, ...props }: ComponentProps<"td">) {
  return <td {...props} data-slot="table-cell" className={cn("px-4 py-3 align-top", className)} />;
}

export function TableCaption({ className, ...props }: ComponentProps<"caption">) {
  return <caption {...props} data-slot="table-caption" className={cn("border-t border-border px-4 py-3 text-sm text-muted-foreground", className)} />;
}

/** Shared text hierarchy for documentation and component content. */
export const typography = {
  pageTitle: "text-4xl font-semibold tracking-tight text-foreground sm:text-5xl",
  sectionTitle: "text-2xl font-semibold tracking-tight text-foreground",
  subsectionTitle: "text-xl font-semibold tracking-tight text-foreground",
  body: "text-base leading-7 text-muted-foreground",
  label: "text-sm font-medium",
  caption: "text-sm leading-6 text-muted-foreground",
} as const;
